                    - (wedge_g1[1] * other[e31])
                    - (wedge_g1[2] * other[e12])
                    - (wedge_g1[3] * other[e45])
                    - (wedge_g2[0] * other[e41])
                    - (wedge_g2[1] * other[e42])
