    //           add/sub      mul      div
    //      f32        3       14        0
    //    simd3        2        5        0
    //    simd4        2        2        0
    // Totals...
    // yes simd        7       21        0
    //  no simd       17       37        0
    fn project_orthogonally_onto(self, other: Plane) -> Self::Output {
        use crate::elements::*;
        let wedge_g0 = Simd32x4::from([
            self[e425] * other[e4125] * -1.0,
            self[e435] * other[e4235] * -1.0,
            self[e415] * other[e4315] * -1.0,
            (self[e315] * other[e4315]) + (self[e125] * other[e4125]),
        ]) + (Simd32x4::from(other[e3215]) * self.group0().with_w(self[e321]))
            + (other.group0().yzxx() * self.group1().zxy().with_w(self[e235]));
        let wedge_g1 = -(self[e423] * other[e4235]) - (self[e431] * other[e4315]) - (self[e412] * other[e4125]);
        Circle::from_groups(
            // e423, e431, e412
            Simd32x3::from(wedge_g1 * -1.0) * other.group0().xyz(),
            // e415, e425, e435, e321
            ((wedge_g0.yzx() * other.group0().zxy()) - (wedge_g0.zxy() * other.group0().yzx())).with_w(wedge_g1 * other[e3215] * -1.0),
            // e235, e315, e125
            (Simd32x3::from(wedge_g0[3]) * other.group0().xyz()) - (Simd32x3::from(other[e3215]) * wedge_g0.xyz()),
        )
    }
