impl ProjectOrthogonallyOnto<Plane> for DipoleInversion {
    type Output = DipoleInversion;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div
    //      f32        3       18        0
    //    simd3        2        7        0
    //    simd4        6        5        0
    // Totals...
    // yes simd       11       30        0
    //  no simd       33       59        0
    fn project_orthogonally_onto(self, other: Plane) -> Self::Output {
        use crate::elements::*;
        let wedge_g0 = (self.group0().yzx() * other.group0().zxy()) - (self.group0().zxy() * other.group0().yzx());
        let wedge_g1 = Simd32x4::from([
            self[e41] * other[e3215],
            self[e42] * other[e3215],
            self[e43] * other[e3215],
            -(self[e31] * other[e4315]) - (self[e12] * other[e4125]),
        ]) - (self.group1().wwwx() * other.group0().xyzx());
        let wedge_g2 = Simd32x4::from([
            self[e25] * other[e4125] * -1.0,
            self[e35] * other[e4235] * -1.0,
            self[e15] * other[e4315] * -1.0,
            (self[e4315] * other[e4315]) + (self[e4125] * other[e4125]),
        ]) + (Simd32x4::from(other[e3215]) * self.group1().xyz().with_w(self[e1234]))
            + (other.group0().yzxx() * self.group2().zxy().with_w(self[e4235]));
        DipoleInversion::from_groups(
            // e41, e42, e43
            (wedge_g0.zxy() * other.group0().yzx()) - (wedge_g0.yzx() * other.group0().zxy()),
            // e23, e31, e12, e45
            Simd32x4::from([
                wedge_g0[0] * other[e3215],
                wedge_g0[1] * other[e3215],
                wedge_g0[2] * other[e3215],
                -(wedge_g1[1] * other[e4315]) - (wedge_g1[2] * other[e4125]),
            ]) - (wedge_g1.wwwx() * other.group0().xyzx()),
            // e15, e25, e35, e1234
            (Simd32x3::from(other[e3215]) * wedge_g1.xyz()).with_w(0.0) + (wedge_g2.yzx() * other.group0().zxy()).with_w(0.0) - (wedge_g2.zxy() * other.group0().yzx()).with_w(0.0),
            // e4235, e4315, e4125, e3215
            Simd32x4::from(wedge_g2[3]) * other.group0(),
        )
    }
}
