impl ProjectOrthogonallyOnto<RoundPoint> for MultiVector {
    type Output = MultiVector;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div
    //      f32        8       14        0
    //    simd4        0        2        0
    // Totals...
    // yes simd        8       16        0
    //  no simd        8       22        0
    fn project_orthogonally_onto(self, other: RoundPoint) -> Self::Output {
        use crate::elements::*;
        let right_anti_dual_g0 = other.group0().xyz().with_w(other[e5] * -1.0);
        let right_anti_dual_g1 = other[e4] * -1.0;
        let wedge_g0_y = (right_anti_dual_g1 * self[e5])
            + (right_anti_dual_g0[0] * self[e1])
            + (right_anti_dual_g0[1] * self[e2])
            + (right_anti_dual_g0[2] * self[e3])
            + (right_anti_dual_g0[3] * self[e4]);
        let wedge_g9 = right_anti_dual_g0 * Simd32x4::from(self[scalar]);
        MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([
                (wedge_g9[0] * other[e1]) + (wedge_g9[1] * other[e2]) + (wedge_g9[2] * other[e3]) + (wedge_g9[3] * other[e4]) + (right_anti_dual_g1 * self[scalar] * other[e5]),
                0.0,
            ]),
            // e1, e2, e3, e4
            Simd32x4::from(wedge_g0_y) * other.group0(),
            // e5
            wedge_g0_y * other[e5],
            // e15, e25, e35, e45
            Simd32x4::from(0.0),
            // e41, e42, e43
            Simd32x3::from(0.0),
            // e23, e31, e12
            Simd32x3::from(0.0),
            // e415, e425, e435, e321
            Simd32x4::from(0.0),
            // e423, e431, e412
            Simd32x3::from(0.0),
            // e235, e315, e125
            Simd32x3::from(0.0),
            // e4235, e4315, e4125, e3215
            Simd32x4::from(0.0),
            // e1234
            0.0,
        )
    }
}
