                (other[e3] * self[e3])
                    - (right_anti_dual_g0[0] * self[e235])
                    - (right_anti_dual_g0[1] * self[e315])
                    - (right_anti_dual_g0[2] * self[e125])
                    - (other[e415] * self[e415])
                    - (other[e425] * self[e425])
                    - (other[e435] * self[e435])
